import static org.junit.Assert.*;

/** Home dialog keys through its own Dialog/focused View, never the OS input injector. */
@RunWith(AndroidJUnit4.class)
public final class RhHomeDialogKeysDeviceTest {
    private final Instrumentation instrument=InstrumentationRegistry.getInstrumentation();
    private final String uuid="ui-dialog-keys117";private final JSONArray cases=new JSONArray();
    private Activity activity;private RhHome home;private File folder;private String kind;private EditText currentEditor;
    private void main(Runnable action){instrument.runOnMainSync(action);instrument.waitForIdleSync();}
    private JSONObject state(){JSONObject[] value={null};main(()->{try{value[0]=home.state();}catch(Exception error){throw new RuntimeException(error);}});return value[0];}
    private void action(String id,JSONObject args){main(()->assertTrue(id,RhActions.dispatch(id,args).optBoolean("ok")));}
    private View find(View view,String label,boolean editor){if(view.getVisibility()!=View.VISIBLE)return null;if(editor&&view instanceof EditText&&label.contentEquals(view.getContentDescription())||!editor&&(view instanceof Button&&label.contentEquals(((Button)view).getText())||label.startsWith("nav:")&&label.equals(view.getTag())))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),label,editor);if(found!=null)return found;}return null;}
    private void click(String label){main(()->{View view=find(activity.findViewById(android.R.id.content),label,false);assertNotNull(label,view);assertTrue(view.isEnabled());Rect area=new Rect();assertTrue(view.getGlobalVisibleRect(area));assertEquals(view.getWidth(),area.width());assertEquals(view.getHeight(),area.height());view.performClick();});}
    private void input(String label,String value){main(()->{currentEditor=(EditText)find(activity.findViewById(android.R.id.content),label,true);assertNotNull(label,currentEditor);currentEditor.requestRectangleOnScreen(new Rect(0,0,currentEditor.getWidth(),currentEditor.getHeight()),true);currentEditor.requestFocusFromTouch();currentEditor.setText(value);});}
    private AlertDialog popup()throws Exception{Field field=RhHome.class.getDeclaredField(kind.equals("clear")?"syncClearDialog":"navigationDialog");field.setAccessible(true);AlertDialog value=(AlertDialog)field.get(home);assertNotNull(value);assertTrue(value.isShowing());long until=SystemClock.uptimeMillis()+3000;boolean[] focused={false};while(!focused[0]){main(()->focused[0]=value.getWindow().getDecorView().hasWindowFocus());assertTrue("Dialog window focus missing",SystemClock.uptimeMillis()<until);if(!focused[0])Thread.sleep(20);}return value;}
    private void open(){click(kind.equals("clear")?"移除同步设置":kind.equals("profile")?"nav:app.settings.open":"nav:devices.open");}
    private void key(AlertDialog popup,int action,int code,int flags){main(()->{long now=SystemClock.uptimeMillis();KeyEvent event=new KeyEvent(now,now,action,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,flags,InputDevice.SOURCE_KEYBOARD);boolean handled=popup.dispatchKeyEvent(event);assertTrue("Local key not handled: "+code,handled);});}
    private void press(AlertDialog popup,int code){key(popup,KeyEvent.ACTION_DOWN,code,0);key(popup,KeyEvent.ACTION_UP,code,0);}
    private String accountHash(Context context)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(new File(context.getFilesDir(),"webdav-local.json").toPath()));StringBuilder value=new StringBuilder();for(byte b:digest)value.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return value.toString();}
    private void capture(AlertDialog popup,String name)throws Exception{Bitmap[] image={null};main(()->{View decor=popup.getWindow().getDecorView();for(int choice:new int[]{AlertDialog.BUTTON_NEUTRAL,AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_POSITIVE}){Button button=popup.getButton(choice);if(button==null||button.getVisibility()!=View.VISIBLE)continue;Rect area=new Rect();assertTrue(button.getGlobalVisibleRect(area));assertEquals(button.getWidth(),area.width());assertEquals(button.getHeight(),area.height());}image[0]=Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),Bitmap.Config.ARGB_8888);decor.draw(new Canvas(image[0]));});try(OutputStream output=new FileOutputStream(new File(folder,name+".png"))){assertTrue(image[0].compress(Bitmap.CompressFormat.PNG,100,output));}finally{image[0].recycle();}}
    private void exercise(Context context,String theme)throws Exception{
        int safe=kind.equals("clear")?AlertDialog.BUTTON_NEGATIVE:AlertDialog.BUTTON_NEUTRAL;String saved=RhShared.canonical(RhShared.read(context)),account=accountHash(context);AlertDialog first=popup();JSONObject[] focus={null};main(()->{View current=first.getCurrentFocus();focus[0]=RhActions.obj("safe",first.getButton(safe).getText(),"safeFocused",first.getButton(safe).hasFocus(),"safeFocusable",first.getButton(safe).isFocusable(),"safeTouchFocusable",first.getButton(safe).isFocusableInTouchMode(),"touchMode",first.getButton(safe).isInTouchMode(),"current",current==null?"null":current.getClass().getName(),"currentLabel",current instanceof TextView?((TextView)current).getText():"");});RhShared.write(new File(folder,kind+"-"+theme+"-initial-focus.json"),focus[0]);assertTrue("Initial safe focus: "+focus[0],first.getButton(safe).hasFocus());capture(first,kind+"-"+theme);press(first,KeyEvent.KEYCODE_ENTER);assertFalse(first.isShowing());assertTrue(state().isNull(kind.equals("clear")?"syncClearPrompt":"navigationPrompt"));assertEquals(saved,RhShared.canonical(RhShared.read(context)));assertEquals(account,accountHash(context));if(currentEditor!=null)assertTrue("Editor focus not restored",currentEditor.hasFocus());
        open();AlertDialog old=popup();key(old,KeyEvent.ACTION_UP,KeyEvent.KEYCODE_ESCAPE,0);assertTrue(old.isShowing());key(old,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_ESCAPE,0);key(old,KeyEvent.ACTION_UP,KeyEvent.KEYCODE_ESCAPE,KeyEvent.FLAG_CANCELED);assertTrue(old.isShowing());key(old,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_ESCAPE,0);main(()->old.getButton(safe).performClick());assertFalse(old.isShowing());open();AlertDialog current=popup();key(current,KeyEvent.ACTION_UP,KeyEvent.KEYCODE_ESCAPE,0);key(old,KeyEvent.ACTION_UP,KeyEvent.KEYCODE_ESCAPE,0);assertTrue(current.isShowing());press(current,KeyEvent.KEYCODE_ESCAPE);assertFalse(current.isShowing());assertEquals(saved,RhShared.canonical(RhShared.read(context)));assertEquals(account,accountHash(context));
        cases.put(RhActions.obj("kind",kind,"theme",theme,"safeChoiceFocused",true,"enterUsedSafeChoice",true,"escapeCanceledLocally",true,"canceledAndOrphanEscapeIgnored",true,"oldDialogIgnored",true,"editorFocusRestored",currentEditor!=null,"savedConfigurationUnchanged",true,"accountFileUnchanged",true));
    }
    @Test public void homeConfirmationsUseSafeChoicesAndLocalEscape()throws Exception{
        String run=InstrumentationRegistry.getArguments().getString("dialogKeysRun","");org.junit.Assume.assumeFalse("Explicit isolated run required",run.isEmpty());assertTrue(run.matches("[a-zA-Z0-9_-]{1,64}"));assertTrue(android.os.Build.HARDWARE.equals("ranchu")||android.os.Build.HARDWARE.equals("goldfish"));Context context=instrument.getTargetContext();folder=new File(context.getExternalFilesDir("ui-evidence"),run);assertFalse(folder.exists());assertTrue(folder.mkdirs());RhSessionFlowDeviceTest owner=new RhSessionFlowDeviceTest();owner.folder=folder;Field local=RhSync.class.getDeclaredField("local");local.setAccessible(true);RhSync sync=RhSyncWork.shared(context).sync;Object originalAccount=local.get(sync);
        try(RhSessionStateSnapshot snapshot=new RhSessionStateSnapshot(owner,run)){
            main(()->{try{JSONObject shared=RhShared.read(context);shared.getJSONArray("devices").put(RhActions.obj("uuid",uuid,"name","UI keyboard fixture","displayName","","address","192.0.2.117","addresses",new JSONArray()));RhShared.apply(context,shared);}catch(Exception error){throw new RuntimeException(error);}});
            for(boolean dark:new boolean[]{false,true}){
                RhShared.theme(context,dark);activity=instrument.startActivitySync(new Intent().setClassName(context,"com.limelight.PcView").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));instrument.waitForIdleSync();Field field=activity.getClass().getDeclaredField("rhHome");field.setAccessible(true);home=(RhHome)field.get(activity);assertFalse(state().getJSONObject("sync").optBoolean("automatic"));main(()->{ComputerDetails device=new ComputerDetails();device.uuid=uuid;device.name="UI keyboard fixture";device.manualAddress=new ComputerDetails.AddressTuple("192.0.2.117",47989);home.update(device);});String theme=dark?"dark":"light";
                kind="profile";action("device.settings.open",RhActions.obj("uuid",uuid));action("settings.tab",RhActions.obj("tab","audio"));String volume="";JSONArray catalog=RhSettings.catalog(context);for(int i=0;i<catalog.length();i++)if(catalog.getJSONObject(i).getString("key").equals("volume"))volume=catalog.getJSONObject(i).getString("label");int changed=RhProfile.load(context,uuid).volume==37?38:37;input(volume,Integer.toString(changed));open();exercise(context,theme);open();AlertDialog save=popup();main(()->assertTrue(save.getButton(AlertDialog.BUTTON_POSITIVE).requestFocusFromTouch()));press(save,KeyEvent.KEYCODE_ENTER);assertEquals(changed,RhProfile.load(context,uuid).volume);assertEquals("global-settings",state().getString("page"));
                kind="info";action("device.info.open",RhActions.obj("uuid",uuid));input("设备名称","键盘草稿");open();exercise(context,theme);open();AlertDialog discard=popup();main(()->assertTrue(discard.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocusFromTouch()));press(discard,KeyEvent.KEYCODE_ENTER);assertEquals("",RhShared.alias(context,uuid));assertEquals("devices",state().getString("page"));
                kind="sync";action("app.settings.tab",RhActions.obj("tab","sync"));input("WebDAV 目录地址（HTTP / HTTPS）","http://fixture.example.test/dav/");open();exercise(context,theme);click("取消");click("nav:devices.open");
                kind="clear";currentEditor=null;local.set(sync,RhActions.obj("url","http://fixture.example.test/dav/","username","fixture-user","ciphertext","fixture-placeholder-not-decrypted","automatic",false,"intervalMinutes",15));action("app.settings.tab",RhActions.obj("tab","sync"));open();exercise(context,theme);click("nav:devices.open");local.set(sync,originalAccount);Activity closing=activity;main(closing::finish);long until=SystemClock.uptimeMillis()+5000;while(!closing.isDestroyed()){assertTrue(SystemClock.uptimeMillis()<until);Thread.sleep(20);}activity=null;
            }
            RhShared.write(new File(folder,"result.json"),RhActions.obj("passed",cases.length()==8,"version",com.limelight.BuildConfig.VERSION_NAME,"fontScale",context.getResources().getConfiguration().fontScale,"cases",cases,"actualPcView",true,"dialogEscapeEvents",true,"dialogEnterEvents",true,"physicalKeyboardUsed",false,"systemInputInjected",false,"normalAccountFileWritten",false,"streamStarted",false,"syncStarted",false));
        }finally{local.set(sync,originalAccount);}
    }
}
